# -*- coding: utf-8 -*-
"""tests/test_worker_restore_guard.py — hooks/worker-restore-guard.py denies the five discarding
forms (ROADMAP row 479) AT THE SHELL BOUNDARY, before a Bash call ever runs, and denies none of the
forms the law explicitly allows.

Twelve real occurrences of the five forms landed inside this project's own working copies in one
24-hour window ending 2026-08-19 (`python3 guardrails/check-worker-restore.py --since-hours 24`),
caught only afterward by that retrospective gate. This hook is the earlier refusal; this suite proves
it fires on every catch the retrospective gate makes and stays silent on every form the law allows —
a false refusal here would stop honest work, which the retrospective gate's own docstring already
names as the worse of the two failures.

Every case runs the ACTUAL script as a subprocess against stdin JSON, the same way
tests/test_scissors_scan.py and the other hook-red-fixtures runs already in this suite do — no
reimplementation of the matcher is exercised here, only the shipped one.
"""
import json
import os
import subprocess
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SCRIPT = os.path.join(ROOT, "hooks", "worker-restore-guard.py")


def _run(command, tool_name="Bash"):
    payload = {"tool_name": tool_name, "tool_input": {"command": command}, "cwd": ROOT}
    return subprocess.run([sys.executable, SCRIPT], input=json.dumps(payload),
                           capture_output=True, text=True, timeout=10)


def _denied(command):
    r = _run(command)
    assert r.returncode == 0, r.stderr
    assert r.stdout.strip(), "expected a deny for %r, hook was silent" % command
    decision = json.loads(r.stdout)
    out = decision["hookSpecificOutput"]
    assert out["hookEventName"] == "PreToolUse"
    assert out["permissionDecision"] == "deny"
    assert out["permissionDecisionReason"]
    return out["permissionDecisionReason"]


def _passed(command):
    r = _run(command)
    assert r.returncode == 0, r.stderr
    assert r.stdout.strip() == "", "expected no deny for %r, got: %s" % (command, r.stdout)


# ---- The five forbidden forms, including the exact shapes the law names -----------------------

def test_checkout_dash_dash_path_denied():
    _denied("git checkout -- TEST_MATRIX.md")


def test_checkout_dot_denied():
